<template>
  <div class="page">
    <div class="content">
      <img class="img" :src="tableData[0].imgUrl" alt="">
      <div class="table">
        <el-table
          :data="[aiResult]"
          border>
          <el-table-column
            prop="createBy"
            label="舌诊项目"
            align="center"
            width="240">
