            prop="imgurl"
            label="图片"
            align="center"
            width="180">
            <template slot-scope="{row}">
              <el-image 
                class="img"
                :src="row.imgUrl" 
                :preview-src-list="[row.imgUrl]">
              </el-image>
            </template>
          </el-table-column> -->
          <el-table-column
            prop="tongueColour"
            label="舌色">
