          <el-table-column
            prop="imgFlag"
            align="center"
            label="图片质量"
            width="120">
            <template slot-scope="{row}">
              <el-tag
                v-if="row.imgFlag !== undefined"
                :type="row.imgFlag === 0 ? 'success' : 'danger'"
                disable-transitions>{{row.imgFlag === 0 ? '合格' : '不合格'}}</el-tag>
            </template>
          </el-table-column>
          <el-table-column
            prop="tongueColour"
            label="舌色">
            <template slot-scope="{row}">
              <span :style="{color: row.tongueColour === aiResult.tongueColour ? '':'red'}">{{row.tongueColour}}</span>
            </template>
          </el-table-column>
          <el-table-column
            prop="tongueShapes"
            label="舌形">
            <template slot-scope="{row}">
