<script>
import { getAllDiagnosisRecord } from '@/service/shezhen';
export default {
  name: 'ShezhenAdminDetail',

  data() {
    return {
      tableData: [],
      aiResult: {}
    };
  },

  mounted() {
    this.aiResult = JSON.parse(this.$route.query.result)
    this.getAllDiagnosisRecord(this.$route.query.id)
  },
  activated(opt) {
    console.log(opt)
  },
  methods: {
    getAllDiagnosisRecord(id) {
      getAllDiagnosisRecord(id).then(res => {
        this.tableData = res
      });
    },
  },
};
</script>

<style>
.page {
  background-color: #FFF;
  padding: 20px;
}
.content {
  display: flex;
  gap: 10px;
}
.img {
  width: 32%;
  flex: 1;
}
.table {
  flex: 2;
}
</style>